hooks.command:
in=$(cat); case "$in" in *maestro*) ;; *) exit 0;; esac; printf '%s' "$in" | python3 -c '
import json, os, re, shlex, sys

payload = json.load(sys.stdin)
tool = payload.get("tool_name", "")
args = payload.get("tool_input") or {}
cwd = os.path.realpath(payload.get("cwd") or os.getcwd())


def decide(decision, reason):
    print(json.dumps({"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": decision,
        "permissionDecisionReason": "Maestro gate: " + reason,
    }}))
    raise SystemExit(0)


risky = re.compile(r"\b(runScript|evalScript|openLink|addMedia)\b")
plain_variable = re.compile(r"\$\{[A-Za-z_][A-Za-z0-9_.]*\}")
flow_reference = re.compile(r"(?:\brunFlow|\bfile):[ \t]*([^\s{#|>-][^\n#]*?)[ \t]*(?:#.*)?$", re.M)
quotes = "\"" + chr(39)
seen = set()


def inspect(text, base, label, depth):
    if depth > 10:
        decide("ask", "runFlow nesting is too deep to inspect.")
    match = risky.search(text)
    if match:
        decide("ask", label + " uses " + match.group(1) + ", which can run code or reach the network outside the sandbox.")
    if "${" in plain_variable.sub("", text):
        decide("ask", label + " has a JavaScript expression beyond a plain ${VAR}, which runs outside the sandbox.")
    for match in flow_reference.finditer(text):
        load(os.path.join(base, match.group(1).strip(quotes)), depth + 1)


def load(path, depth=0):
    path = os.path.realpath(path)
    if path in seen:
        return
    seen.add(path)
    try:
        with open(path, encoding="utf-8") as handle:
            text = handle.read()
    except (OSError, UnicodeDecodeError) as error:
        decide("ask", "cannot read " + path + " to inspect it (" + str(error) + ").")
    inspect(text, os.path.dirname(path), path, depth)


def inspect_path(path):
    if not os.path.isdir(path):
        load(path)
        return
    for folder, _, names in os.walk(path):
        for name in sorted(names):
            if name.endswith((".yaml", ".yml")):
                load(os.path.join(folder, name))


def check_env(values):
    for value in values:
        if "${" in str(value):
            decide("ask", "an env value holds a ${...} expression, which may run as JavaScript outside the sandbox.")


def inside_cwd(path):
    target = os.path.realpath(os.path.join(cwd, path))
    return target == cwd or target.startswith(cwd + os.sep)


allowed = "every flow uses only device commands and plain ${VAR} values."

if tool == "Bash":
    command = args.get("command", "")
    try:
        argv = shlex.split(command)
    except ValueError:
        raise SystemExit(0)
    if not argv or os.path.basename(argv[0]) != "maestro":
        raise SystemExit(0)
    if re.search(r"[;&|<>`$(){}\n]", command):
        decide("ask", "compound or substituted maestro command; run it as one bare command.")
    value_options = {
        "--device", "--udid", "-p", "--platform", "-e", "--env", "--format", "--output",
        "--debug-output", "--test-output-dir", "--include-tags", "--exclude-tags", "--config",
        "--shard-split", "--shard-all", "--test-suite-name", "--host", "--port", "--api-key",
        "--api-url", "--project-id", "--app-file", "--flows", "--name", "--app-binary-id",
    }
    options, positionals, rest, index = [], [], argv[1:], 0
    while index < len(rest):
        token = rest[index]
        if token.startswith("-") and token != "-":
            name, equals, value = token.partition("=")
            if not equals and name in value_options and index + 1 < len(rest):
                index += 1
                value = rest[index]
            options.append((name, value))
        else:
            positionals.append(token)
        index += 1
    if not positionals:
        if options and all(name in {"--version", "-v", "--help", "-h"} for name, _ in options):
            decide("allow", "maestro only prints its version or help.")
        decide("ask", "maestro with no subcommand to inspect.")
    if positionals[0] != "test":
        decide("ask", "maestro " + positionals[0] + " is not a local flow run.")
    if len(positionals) < 2:
        decide("ask", "maestro test names no flow to inspect.")
    for name, value in options:
        if name in {"-c", "--continuous"}:
            decide("ask", "continuous mode re-runs flows after they change without inspecting them again.")
        if name in {"--api-key", "--api-url"}:
            decide("ask", name + " sends the run to a Maestro service.")
        if name in {"--output", "--debug-output", "--test-output-dir"} and not inside_cwd(value):
            decide("ask", name + " writes outside the project: " + value)
        if name in {"-e", "--env"}:
            check_env([value])
        if name == "--config":
            load(os.path.join(cwd, value))
    for flow in positionals[1:]:
        inspect_path(os.path.join(cwd, flow))
    decide("allow", allowed)

if not re.fullmatch(r"mcp__[^_]*maestro[^_]*__run", tool):
    raise SystemExit(0)
if isinstance(args.get("env"), dict):
    check_env(args["env"].values())
if isinstance(args.get("yaml"), str):
    inspect(args["yaml"], cwd, "the inline flow", 0)
elif isinstance(args.get("files"), list) and args["files"]:
    for name in args["files"]:
        load(os.path.join(cwd, str(name)))
elif isinstance(args.get("dir"), str):
    root = os.path.join(cwd, args["dir"])
    if not os.path.isdir(root):
        decide("ask", "cannot read directory " + root + " to inspect it.")
    inspect_path(root)
else:
    raise SystemExit(0)
decide("allow", allowed)
'
